// [Decide] 발송 여부 판단 (n8n Code 노드, Run Once for Each Item)
// 입력: Split Alerts(알림), Get Weather(Open-Meteo), Get Travel Time(카카오모빌리티)
// 출력: shouldSend, reason, dispatch 요청 본문

function decide(alert, weatherRes, routeRes, nowDate) {
  const now = nowDate || new Date();
  const arrival = alert.arrival_at ? new Date(alert.arrival_at) : null;
  const buffer = Number(alert.buffer_minutes || 10);

  // 1) 날씨 정리
  const WEATHER_CODES = [
    [0, 0, '맑음'], [1, 3, '구름 조금~흐림'], [45, 48, '안개'],
    [51, 57, '이슬비'], [61, 67, '비'], [71, 77, '눈'],
    [80, 82, '소나기'], [85, 86, '눈 소나기'], [95, 99, '뇌우'],
  ];
  let weather = null;
  if (weatherRes && weatherRes.current) {
    const cur = weatherRes.current;
    const code = cur.weather_code;
    const found = WEATHER_CODES.find(([a, b]) => code >= a && code <= b);
    // 지금부터 도착 시각까지 시간대별 강수확률 중 최댓값
    let maxProb = null;
    const hourly = weatherRes.hourly || {};
    const times = hourly.time || [];
    const probs = hourly.precipitation_probability || [];
    const end = arrival || new Date(now.getTime() + 3 * 3600 * 1000);
    for (let i = 0; i < times.length; i++) {
      const t = new Date(times[i] + ':00+09:00');
      if (t.getTime() >= now.getTime() - 3600 * 1000 && t.getTime() <= end.getTime()) {
        if (probs[i] != null && (maxProb === null || probs[i] > maxProb)) maxProb = probs[i];
      }
    }
    weather = {
      temperature: cur.temperature_2m ?? null,
      precipitation: cur.precipitation ?? null,
      precipitation_probability: maxProb,
      summary: found ? found[2] : null,
    };
  }

  // 2) 이동 시간
  let travelMinutes = null;
  const route = routeRes && Array.isArray(routeRes.routes) ? routeRes.routes[0] : null;
  if (route && route.result_code === 0 && route.summary && route.summary.duration != null) {
    travelMinutes = Math.round(route.summary.duration / 60);
  }
  let leaveAt = null;
  if (arrival && travelMinutes !== null) {
    leaveAt = new Date(arrival.getTime() - (travelMinutes + buffer) * 60 * 1000);
  }

  // 3) 조건 확인 (조건이 있는데 날씨를 못 가져오면 다음 주기에 다시 확인)
  let conditionOk = true;
  let reason = '';
  const cond = alert.condition;
  if (cond && cond.type) {
    if (!weather) {
      conditionOk = false;
      reason = '날씨 정보 없음';
    } else if (cond.type === 'rain') {
      const threshold = cond.value != null ? Number(cond.value) : 50;
      conditionOk = (weather.precipitation_probability ?? 0) >= threshold || (weather.precipitation ?? 0) > 0;
      if (!conditionOk) reason = '비 예보 없음';
    } else if (cond.type === 'temp_below') {
      conditionOk = weather.temperature !== null && weather.temperature < Number(cond.value ?? 0);
      if (!conditionOk) reason = '기온 조건 미충족';
    } else if (cond.type === 'temp_above') {
      conditionOk = weather.temperature !== null && weather.temperature > Number(cond.value ?? 30);
      if (!conditionOk) reason = '기온 조건 미충족';
    }
  }

  // 4) 발송 시점 확인 (워크플로우가 10분마다 돌므로 출발 10분 전부터 발송)
  let timeOk = true;
  if (alert.notify_mode === 'departure') {
    const LEAD_MS = 10 * 60 * 1000;
    if (leaveAt) {
      timeOk = now.getTime() >= leaveAt.getTime() - LEAD_MS;
    } else if (arrival) {
      // 이동 시간을 못 구하면 도착 60분 전에 발송
      timeOk = now.getTime() >= arrival.getTime() - 60 * 60 * 1000;
    }
    if (!timeOk && !reason) reason = '아직 출발 시각 전';
  }

  return {
    alert_id: alert.id,
    user_id: alert.user_id,
    shouldSend: conditionOk && timeOk,
    reason: conditionOk && timeOk ? '발송' : reason,
    leave_at: leaveAt ? leaveAt.toISOString() : null,
    travel_minutes: travelMinutes,
    weather,
    payload: {
      user_id: alert.user_id,
      weather,
      travel_minutes: travelMinutes,
      leave_at: leaveAt ? leaveAt.toISOString() : null,
    },
  };
}

// n8n 실행부
const alert = $('Split Alerts').item.json;
const weatherRes = $('Get Weather').item.json;
const routeRes = $('Get Travel Time').item.json;
return { json: decide(alert, weatherRes, routeRes, new Date()) };
